-- Source-backed visual marking content for 9618/11/M/J/21.
-- Literal review of the SHA-pinned Cambridge mark scheme found eight visual
-- answer elements that were represented only as prose/atomic points and had no
-- mark_scheme_assets rows. All are reproducible code-based visuals; no raster
-- source image is required. source_bbox uses PDF-point [x1,y1,x2,y2] geometry,
-- derived from exact 200-DPI source renders and recorded again in structure_json.
-- Staging only: do not apply to production until preview/export evidence passes.

DO $$
DECLARE
  v_source uuid := 'fa26b542-9ad7-4ebd-89a5-eab2d4695fc6'::uuid;
  v_sha text := 'e0c2cd4128ec9e2491d8ef2befe7674281dd934cb366f72cbcc6ee026fef6733';
  v_svg text;
  v_hash text;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM source_papers sp
    WHERE sp.id=v_source AND sp.kind='MS' AND sp.sha256=v_sha AND sp.page_count=10
  ) THEN
    RAISE EXCEPTION 'ms11_visual_source_provenance_mismatch';
  END IF;

  v_svg := $msvf0$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 162" role="img"><rect width="300" height="162" fill="white"/><style>.c{font-family:"Courier New",monospace;font-size:20px;fill:#111}</style><text class="c" x="10" y="28">0010 0011</text><text class="c" x="10" y="56">+ 0000 1111</text><text class="c" x="10" y="84">-----------</text><text class="c" x="10" y="112">0011 0010</text><text class="c" x="10" y="140">   1   111</text></svg>$msvf0$;
  v_hash := encode(digest(v_svg,'sha256'),'hex');
  IF NOT EXISTS (
    SELECT 1 FROM mark_schemes ms
    WHERE ms.id='22d0d5d3-3f9e-43b1-a4b4-ab69ad53df49'::uuid
      AND ms.source_paper_id=v_source
      AND ms.status='approved'
  ) THEN
    RAISE EXCEPTION 'ms11_visual_1_mark_scheme_provenance_mismatch';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM mark_scheme_assets msa
    WHERE msa.mark_scheme_id='22d0d5d3-3f9e-43b1-a4b4-ab69ad53df49'::uuid
      AND msa.source_paper_id=v_source
      AND msa.source_sha256=v_sha
      AND msa.content_hash=v_hash
  ) THEN
    INSERT INTO mark_scheme_assets(
      id,mark_scheme_id,source_paper_id,source_sha256,kind,content_md,alt_text,
      source_page,source_bbox,structure_json,content_hash,sort_order
    ) VALUES (
      gen_random_uuid(),'22d0d5d3-3f9e-43b1-a4b4-ab69ad53df49'::uuid,v_source,v_sha,'code',v_svg,
      'Official Cambridge binary addition working for Q1(c)(ii)',3,'[134.6,480.2,198,536.8]'::jsonb,
      '{"representation":"SVG-CODE","sourcePixelBbox200Dpi":[374,1334,550,1491],"lines":["0010 0011","+ 0000 1111","-----------","0011 0010","1 111"]}'::jsonb,v_hash,0
    );
  END IF;

  v_svg := $msvf1$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 330 246" role="img"><rect width="330" height="246" fill="white"/><style>.c{font-family:"Courier New",monospace;font-size:20px;fill:#111}</style><text class="c" x="10" y="28">10  = 0000 1010</text><text class="c" x="10" y="56">−10 = 1111 0110</text><text class="c" x="10" y="84"></text><text class="c" x="10" y="112">0010 0011</text><text class="c" x="10" y="140">+ 1111 0110</text><text class="c" x="10" y="168">-----------</text><text class="c" x="10" y="196">0001 1001</text><text class="c" x="10" y="224">11   11</text></svg>$msvf1$;
